"use client";

import { useState } from "react";
import { BookOpen, Check, ChevronRight, Play } from "lucide-react";
import { cn } from "@/lib/utils";
import { panel, secondary } from "@/lib/takt-surface";

type Lesson = {
  id: string;
  title: string;
  complete?: boolean;
  href?: string;
  excerpt?: string;
};
const lessons: Lesson[] = [
  {
    id: "01",
    title: "Characters and classes",
    complete: true,
    excerpt: "The [0-9] class matches one digit.",
  },
  {
    id: "02",
    title: "Repeating a pattern",
    excerpt:
      "Add + after the class to accept consecutive characters.",
  },
  {
    id: "03",
    title: "String boundaries",
    excerpt: "The ^ and $ anchors mark the start and end of a string.",
  },
];
export function LessonOutline({
  title = "Regular expressions",
  items = lessons,
  currentId,
  onResume,
  className,
}: {
  title?: string;
  items?: Lesson[];
  currentId?: string;
  onResume?: (id: string) => void;
  className?: string;
}) {
  const [selected, setSelected] = useState<string>(currentId ?? "");
  const [opened, setOpened] = useState<string>();
  const current =
    items.find((item) => item.id === selected) ??
    items.find((item) => !item.complete) ??
    items[0];
  const completed = items.filter((item) => item.complete).length;
  return (
    <nav
      aria-label="Course outline"
      className={cn(panel, "grid w-72 max-w-full gap-3", className)}
    >
      <div className="flex items-center justify-between">
        <BookOpen size={17} />
        <span className="font-mono text-xs text-muted-foreground">
          {completed} / {items.length}
        </span>
      </div>
      <strong className="text-lg leading-tight tracking-tight">{title}</strong>
      <ol>
        {items.map((item, i) => (
          <li key={item.id}>
            <button
              type="button"
              onClick={() => {
                setSelected(item.id);
                setOpened(undefined);
              }}
              aria-current={current?.id === item.id ? "step" : undefined}
              className="flex w-full items-center gap-2 rounded-md px-2 py-2 text-start text-xs aria-[current=step]:bg-muted motion-safe:transition-colors"
            >
              <span className="grid size-5 shrink-0 place-items-center rounded-full border font-mono text-[10px]">
                {item.complete ? <Check size={11} /> : i + 1}
              </span>
              {item.title}
              {current?.id === item.id && (
                <ChevronRight
                  size={13}
                  className="ml-auto text-primary motion-safe:animate-in motion-safe:slide-in-from-left-1"
                />
              )}
            </button>
          </li>
        ))}
      </ol>
      {current &&
        (current.href ? (
          <a
            href={current.href}
            onClick={() => onResume?.(current.id)}
            className={secondary}
          >
            Open lesson
          </a>
        ) : (
          <button
            type="button"
            className={secondary}
            onClick={() => {
              setOpened(current.id);
              onResume?.(current.id);
            }}
          >
            <Play size={12} />
            Open lesson
          </button>
        ))}
      {opened === current?.id && current && (
        <div
          role="status"
          className="rounded-lg bg-muted p-3 text-xs leading-relaxed motion-safe:animate-in motion-safe:slide-in-from-top-1"
        >
          <strong>{current.title}</strong>
          {current.excerpt && <p className="mt-1">{current.excerpt}</p>}
        </div>
      )}
    </nav>
  );
}

// Semantic shadcn colors keep the surfaces usable in a host project's own theme.
export const panel =
  "rounded-2xl border border-foreground/10 bg-card p-4 text-sm text-card-foreground shadow-[0_2px_5px_#0000000a,0_8px_18px_-12px_#0003]";
export const field =
  "min-h-10 min-w-0 w-full rounded-xl border border-foreground/10 bg-muted/70 px-3 text-sm text-foreground outline-none motion-safe:transition-[background-color,box-shadow] focus:bg-background focus:ring-1 focus:ring-foreground/35";
export const action =
  "inline-flex min-h-10 cursor-pointer items-center justify-center gap-2 rounded-xl border border-foreground/10 bg-primary px-3.5 py-2 text-sm font-semibold text-primary-foreground shadow-sm outline-offset-4 motion-safe:transition-[transform,box-shadow] motion-safe:active:translate-y-px motion-safe:active:scale-[.97] disabled:cursor-default disabled:opacity-50";
export const secondary =
  "inline-flex min-h-9 cursor-pointer items-center justify-center gap-1.5 rounded-lg border border-foreground/10 bg-background px-3 text-xs font-medium text-foreground outline-offset-2 hover:bg-muted motion-safe:transition-[transform,background-color] motion-safe:active:scale-[.96] disabled:cursor-default disabled:opacity-45";
